package it.frociart.app;
import java.util.*;import java.util.function.*;import java.util.stream.Collectors;
import static it.frociart.app.FlowModel.*;

/** Emits standalone C++17 instructions, preserving evaluation order and source origins. */
final class FlowCpp {
 private FlowCpp(){}
 static FlowSourceText generate(FlowSource.Program program,String runtime){return generate(program,runtime,"fc_program");}
 static FlowSourceText generate(FlowSource.Program program,String runtime,String programName){if(runtime==null||runtime.trim().isEmpty())throw new IllegalArgumentException("Il supporto C++ è vuoto.");if(programName==null||!programName.matches("[A-Za-z][A-Za-z_0-9]*")||KEYWORDS.contains(programName)||programName.contains("__")||programName.equals("std")||programName.equals("frociart_support"))throw new IllegalArgumentException("Nome C++ non valido.");return new Writer(program).generate(runtime,programName);}
 static String literal(String text){if(text==null)return "Text()";StringBuilder b=new StringBuilder("Text(u\"");for(char c:text.toCharArray()){if(c=='"')b.append("\\\"");else if(c=='\\')b.append("\\\\");else if(c=='\n')b.append("\\n");else if(c=='\r')b.append("\\r");else if(c=='\t')b.append("\\t");else if(c<32||c>126)b.append("\\x").append(String.format(Locale.ROOT,"%04x",(int)c)).append("\" u\"");else b.append(c);}return b.append("\", ").append(text.length()).append(')').toString();}
 private static final Set<String> KEYWORDS=new HashSet<>(Arrays.asList(("alignas alignof and and_eq asm atomic_cancel atomic_commit atomic_noexcept auto bitand bitor bool break case catch char char8_t char16_t char32_t class compl concept const consteval constexpr constinit const_cast continue co_await co_return co_yield decltype default delete do double dynamic_cast else enum explicit export extern false float for friend goto if inline int long mutable namespace new noexcept not not_eq nullptr operator or or_eq private protected public reflexpr register reinterpret_cast requires return short signed sizeof static static_assert static_cast struct switch synchronized template this thread_local throw true try typedef typeid typename union unsigned using virtual void volatile wchar_t while xor xor_eq").split(" ")));
 private static final Set<String> RESERVED=new HashSet<>(Arrays.asList(("fc Value Vector Text TypeSpec HostRuntime Runtime std frociart_support run current checkType convert integer numberFromBits Scope0").split(" ")));
 private static String identifier(String name){if(name.matches("[A-Za-z][A-Za-z_0-9]*")&&!name.contains("__")&&!KEYWORDS.contains(name)&&!RESERVED.contains(name)&&!name.startsWith("fc_"))return name;StringBuilder b=new StringBuilder("flowValue");for(char c:name.toCharArray())b.append(String.format(Locale.ROOT,"%04x",(int)c));return b.toString();}
 private static String unique(String seed,Set<String> names){String result=seed;int n=2;while(!names.add(result))result=seed+"_"+(n++);return result;}
 private static String number(double n){if(n==0)return "Value::number(0.0)";if(Math.abs(n)<=9000000000d){long power=1;for(int digits=0;digits<=6;digits++,power*=10){double scaled=n*power;if(scaled!=Math.floor(scaled))continue;String text=Long.toString((long)Math.abs(scaled));while(text.length()<digits+1)text="0"+text;if(digits>0)text=text.substring(0,text.length()-digits)+"."+text.substring(text.length()-digits);if(n<0)text="-"+text;if(Double.parseDouble(text)==n)return "Value::number("+text+(digits==0?".0":"")+")";}}return String.format(Locale.ROOT,"Value::number(numberFromBits(0x%016xULL))",Double.doubleToLongBits(n));}
 static String templateNumber(double n){return number(n);}
 private static Set<String> caseSet(){return new TreeSet<>(String.CASE_INSENSITIVE_ORDER);}
 private static Set<String> caseSet(Collection<String> source){Set<String> set=caseSet();set.addAll(source);return set;}
 private static final class Symbol{final String name,original;Symbol(String n,String o){name=n;original=o;}}
 private static final class Helper{final String name;final FlowSource.Expression expression;final FlowSource.Block block;final Set<String> staged;final boolean track;Helper(String n,FlowSource.Expression e,FlowSource.Block b,Set<String> s,boolean t){name=n;expression=e;block=b;staged=caseSet(s);track=t;}}
 private static final class Writer {
  final FlowSource.Program program;final FlowSourceText.Builder output;final boolean references;final Map<String,String> functions=new HashMap<>(),classes=new HashMap<>();
  FlowSource.Scope scope;Map<String,Symbol> names;List<Symbol> symbols;Map<String,String> methods;List<Helper> helpers;int temporary;
  Writer(FlowSource.Program p){program=p;output=new FlowSourceText.Builder(p,"cpp");boolean refs=false;for(FlowSource.Scope s:p.scopes)for(FlowSource.Parameter param:s.parameters)refs|=param.byReference;references=refs;int index=0;Set<String> used=new HashSet<>(RESERVED);for(FlowSource.Scope s:p.scopes){classes.put(s.id,"FcScope"+(index++));if(s.id!=null)functions.put(s.id,unique("flow_"+identifier(s.name),used));}}
  void line(String text,int indent,FlowSource.Block block){output.addLine(text,indent,block==null?new FlowSourceText.Origin[0]:new FlowSourceText.Origin[]{new FlowSourceText.Origin(scope.id,block.id)});}
  void line(String text,int indent){line(text,indent,null);}
  String args(FlowSource.Scope s,boolean types){List<String> result=new ArrayList<>();for(int i=0;i<s.parameters.size();i++)result.add((types?"Value ":"")+"fc_arg"+i);return String.join(", ",result);}
  FlowSourceText generate(String runtime,String programName){line("// Generato con Frociart — autore del software: mamt104",0);line("// Progetto: "+literal(program.title),0);line("// C++17. Salva Programma.cpp; compila con g++ -std=c++17 -O2 Programma.cpp -o Programma.",0);line("// Su Linux/macOS aggiungi -pthread.",0);line("// Percorsi e permessi sono quelli del programma eseguito sul computer.",0);
   line("// --- Supporto dei tipi, dei limiti e delle operazioni di Frociart ---",0);for(String text:runtime.replace("\r\n","\n").replace('\r','\n').split("\n",-1))line(text,0);line("// --- Programma ---",0);line("namespace "+programName+" {",0);line("using namespace frociart_support;",1);line("static HostRuntime fc;",1);
   for(FlowSource.Scope s:program.scopes)if(s.id!=null)line("static Value "+functions.get(s.id)+"("+args(s,true)+");",1);
   for(FlowSource.Scope s:program.scopes)writeScope(s);
   for(FlowSource.Scope s:program.scopes)if(s.id!=null){line("static Value "+functions.get(s.id)+"("+args(s,true)+") {",1);line("return std::make_unique<"+classes.get(s.id)+">()->run("+args(s,false)+");",2);line("}",1);}
   line("bool execute(bool saveDrawing = true) { return fc.run([](){ return std::make_unique<FcScope0>()->run(); }, saveDrawing); }",1);line("}",0);line("int main() { return "+programName+"::execute() ? 0 : 1; }",0);return output.build();
  }
  void collect(FlowSource.Expression e,Consumer<String> add){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add.accept(e.text);for(FlowSource.Expression c:e.children)collect(c,add);}
  void writeScope(FlowSource.Scope s){scope=s;temporary=0;names=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);symbols=new ArrayList<>();methods=new HashMap<>();helpers=new ArrayList<>();Set<String> used=new HashSet<>(RESERVED);
   Consumer<String> add=n->{if(n!=null&&!names.containsKey(n)){Symbol symbol=new Symbol(unique("flowVar_"+identifier(n),used),n);names.put(n,symbol);symbols.add(symbol);}};for(FlowSource.Parameter p:s.parameters)add.accept(p.name);int index=0;
   for(FlowSource.Block b:s.blocks){methods.put(b.id,"fc_block"+(index++));FlowSource.Operation o=b.operation;if(o.input!=null){add.accept(o.input.name);collect(o.input.index,add);}if(o.declaration!=null){for(String n:o.declaration.names)add.accept(n);collect(o.declaration.size,add);}for(FlowSource.Write w:o.writes){add.accept(w.target.name);collect(w.value,add);collect(w.target.index,add);}collect(o.value,add);}
   line("",0);for(FlowSource.Block n:s.notes)line("// Annotazione: "+literal(n.text),1,n);for(FlowSource.Block n:s.blocks)if(n.comment!=null&&!n.comment.isEmpty())line("// Nota: "+literal(n.comment),1,n);
   line("class "+classes.get(s.id)+" {",1);for(Symbol symbol:symbols){line("Value "+symbol.name+";",2);line("std::optional<TypeSpec> fc_type_"+symbol.name+";",2);}for(FlowSource.Parameter p:s.parameters)line("const TypeSpec fc_parameter_"+names.get(p.name).name+"{"+p.type+", "+p.isArray+", 0};",2);
   line("public:",1);line("Value run("+args(s,true)+") {",2);line("fc.guardCall();",3);index=0;for(FlowSource.Parameter p:s.parameters){String argument="fc_arg"+(index++);line(names.get(p.name).name+" = "+(p.byReference?"fc.checkReference("+argument+", "+p.type+")":"checkType("+argument+", "+p.type+", "+p.isArray+")")+";",3);}
   String parameterNames=s.parameters.stream().map(p->literal(names.get(p.name).original)).collect(Collectors.joining(", "));
   line("return fc.invoke("+(s.id==null?"std::nullopt":"std::optional<Text>("+literal(s.name)+")")+", {"+parameterNames+"}, {"+args(s,false)+"}, [&]() -> Value {",3);
   FlowSourcePlan plan=FlowSourcePlan.create(s);if(plan.structured)statements(plan.statements,4);else explicit(4);line("}, "+references+");",3);line("}",2);line("private:",1);for(FlowSource.Block b:s.blocks)instruction(b);
   for(int i=0;i<helpers.size();i++){Helper h=helpers.get(i);line("Value "+h.name+"() {",2,h.block);String expr=expression(h.expression,h.block,h.staged,0,h.track);line("return "+expr+";",3,h.block);line("}",2,h.block);}line("};",1);
  }
  String name(String name,Set<String> staged){Symbol sym=names.get(name);String value=references?"fc.current("+literal(sym.original)+")":staged.contains(sym.original)?"fc.staged("+literal(sym.original)+")":sym.name;return "fc.value("+value+", "+literal(name)+")";}
  String declaration(String name){String n=names.get(name).name;return "(fc_type_"+n+" ? &*fc_type_"+n+" : nullptr)";}
  String parameter(String name){for(FlowSource.Parameter p:scope.parameters)if(p.name.equalsIgnoreCase(name))return "&fc_parameter_"+names.get(name).name;return "nullptr";}
  boolean calls(FlowSource.Expression e){if(e==null)return false;if(e.functionId!=null)return true;for(FlowSource.Expression c:e.children)if(calls(c))return true;return false;}
  String expression(FlowSource.Expression e,FlowSource.Block b){return expression(e,b,caseSet(),0,false);}
  String expression(FlowSource.Expression e,FlowSource.Block block,Set<String> staged,int depth,boolean initialTrack){if(e==null)return "Value()";final boolean track=initialTrack||(depth==0&&calls(e));if(depth>=24){String helper="fc_expr"+(++temporary);helpers.add(new Helper(helper,e,block,staged,track));return helper+"()";}
   int key=track?++temporary:0;java.util.function.Function<FlowSource.Expression,String> child=c->{String v=expression(c,block,staged,depth+1,track);return track?"fc.hold("+key+", "+v+")":v;};java.util.function.Function<String,String> finish=v->track&&!e.children.isEmpty()?"fc.release("+key+", "+v+")":v;
   switch(e.kind){case Number:return number(e.number);case Text:return "Value::text("+literal(e.text)+")";case Boolean:return "Value::logical("+e.bool+")";case Variable:return name(e.text,staged);case Vector:return finish.apply("Value::vector({"+e.children.stream().map(child).collect(Collectors.joining(", "))+"})");
    case Index:{boolean named=references&&e.children.get(0).kind==FlowSource.ExpressionKind.Variable;return finish.apply(named?"fc.atName("+literal(names.get(e.children.get(0).text).original)+", [&](){ return "+child.apply(e.children.get(1))+"; })":"fc.at("+child.apply(e.children.get(0))+", [&](){ return "+child.apply(e.children.get(1))+"; })");}
    case Unary:return finish.apply("fc.unary(\""+e.text+"\", "+child.apply(e.children.get(0))+")");
    case Binary:{String a=child.apply(e.children.get(0)),c=child.apply(e.children.get(1));if(e.text.equals("and")||e.text.equals("or"))return finish.apply("Value::logical(("+a+").asBoolean() "+(e.text.equals("and")?"&&":"||")+" ("+c+").asBoolean())");return "([&]() -> Value { auto fc_left = "+a+"; auto fc_right = "+c+"; return "+finish.apply("fc.binary(\""+e.text+"\", fc_left, fc_right)")+"; }())";}
    case Call:{if(e.functionId==null)return finish.apply("fc.intrinsic(\""+e.text+"\", {"+e.children.stream().map(child).collect(Collectors.joining(", "))+"})");FlowSource.Scope target=null;for(FlowSource.Scope s:program.scopes)if(e.functionId.equals(s.id)){target=s;break;}if(target==null)throw new IllegalArgumentException("Funzione mancante nel sorgente.");List<String> parts=new ArrayList<>(),arguments=new ArrayList<>();for(int i=0;i<e.children.size();i++){FlowSource.Expression c=e.children.get(i);String value=target.parameters.get(i).byReference?"fc.hold("+key+", fc.reference("+literal(names.get(c.text).original)+", "+declaration(c.text)+", "+parameter(c.text)+"))":child.apply(c);parts.add("auto fc_argument"+i+" = "+value+"; ");arguments.add("fc_argument"+i);}return "fc.call("+key+", [&]() -> Value { "+String.join("",parts)+"return "+functions.get(e.functionId)+"("+String.join(", ",arguments)+"); })";}
    default:throw new IllegalArgumentException("Espressione C++ non supportata.");}
  }
  void statements(List<FlowSourcePlan.Statement> list,int indent){for(FlowSourcePlan.Statement s:list){if(s.kind==FlowSourcePlan.Kind.Instruction)line((s.block.kind==END?"return ":"")+methods.get(s.block.id)+"();",indent,s.block);else if(s.kind==FlowSourcePlan.Kind.Repeat){line("do {",indent,s.entryBlock());statements(s.body,indent+1);line("} while ("+(s.loopOnTrue?"":"!")+methods.get(s.block.id)+"().asBoolean());",indent,s.block);}else if(s.kind==FlowSourcePlan.Kind.While){line("while ("+(s.loopOnTrue?"":"!")+methods.get(s.block.id)+"().asBoolean()) {",indent,s.block);statements(s.body,indent+1);line("}",indent,s.block);}else{line("if ("+methods.get(s.block.id)+"().asBoolean()) {",indent,s.block);statements(s.body,indent+1);line("} else {",indent,s.block);statements(s.otherwise,indent+1);line("}",indent,s.block);}}}
  void explicit(int indent){line("// Collegamenti espliciti per conservare questo grafo.",indent);Map<String,Integer> ids=new HashMap<>();for(int i=0;i<scope.blocks.size();i++)ids.put(scope.blocks.get(i).id,i);line("int fc_next = "+ids.get(scope.startId)+";",indent);line("while (true) {",indent);line("switch (fc_next) {",indent+1);for(FlowSource.Block b:scope.blocks){line("case "+ids.get(b.id)+":",indent+2,b);if(b.kind==END)line("return "+methods.get(b.id)+"();",indent+3,b);else if(b.kind==DECISION)line("fc_next = "+methods.get(b.id)+"().asBoolean() ? "+ids.get(b.next("true"))+" : "+ids.get(b.next("false"))+"; break;",indent+3,b);else{line(methods.get(b.id)+"();",indent+3,b);line("fc_next = "+ids.get(b.next("next"))+"; break;",indent+3,b);}}line("default: throw Problem(\"Collegamento non valido nel sorgente modificato.\");",indent+2);line("}",indent+1);line("}",indent);}
  void instruction(FlowSource.Block b){FlowSource.Operation o=b.operation;line("Value "+methods.get(b.id)+"() {",2,b);Consumer<String> emit=t->line(t,3,b);if(b.kind==DECISION){emit.accept("return Value::logical(fc.test([&](){ return "+expression(o.value,b)+"; }));");line("}",2,b);return;}emit.accept(b.kind==INPUT?"fc.guard();":"fc.step();");
   if(b.kind==END){if(scope.id==null)emit.accept("fc.finishFiles();");emit.accept(scope.id==null||scope.returnType==VOID?"return Value();":"return checkType("+expression(o.value,b)+", "+scope.returnType+", "+scope.returnIsArray+");");line("}",2,b);return;}
   if(b.kind==PROCESS){emit.accept("fc.begin();");Set<String> staged=caseSet();List<String> assignments=new ArrayList<>();for(FlowSource.Write w:o.writes)assignments.add("fc_assign"+(++temporary));for(String assignment:assignments)emit.accept(assignment+"();");emit.accept("fc.commit();");for(FlowSource.Write w:o.writes)if(staged.add(names.get(w.target.name).original))emit.accept(names.get(w.target.name).name+" = fc.variable("+literal(names.get(w.target.name).original)+");");emit.accept("return Value();");line("}",2,b);staged.clear();for(int i=0;i<o.writes.size();i++){FlowSource.Write w=o.writes.get(i);line("void "+assignments.get(i)+"() {",2,b);line("auto fc_value = "+expression(w.value,b,staged,0,false)+";",3,b);if(w.target.index!=null)line("fc_value = "+(references?"fc.setAfterName(fc_value, "+literal(names.get(w.target.name).original):"fc.setAfter(fc_value, "+name(w.target.name,staged))+", [&](){ return "+expression(w.target.index,b,staged,0,false)+"; });",3,b);line("fc.stage("+literal(names.get(w.target.name).original)+", convert(fc_value, "+declaration(w.target.name)+", "+parameter(w.target.name)+"), true, "+(w.target.index!=null)+");",3,b);line("}",2,b);staged.add(names.get(w.target.name).original);}return;}
   if(b.kind==DECLARE){FlowSource.Declaration d=o.declaration;emit.accept("int fc_size = integer("+(d.isArray()?expression(d.size,b):"Value::number(0)")+", 0, 1024, \"La dimensione\");");emit.accept("fc.begin();");for(String n:d.names)emit.accept("fc.stage("+literal(names.get(n).original)+", initial("+d.type+", "+d.isArray()+", fc_size), false);");emit.accept("fc.commit(true);");for(String n:d.names){emit.accept(names.get(n).name+" = fc.variable("+literal(names.get(n).original)+");");emit.accept("fc_type_"+names.get(n).name+" = TypeSpec{"+d.type+", "+d.isArray()+", fc_size};");}}
   else if(b.kind==INPUT||b.kind==READ_FILE){FlowSource.Target t=o.input;String tail=declaration(t.name)+", "+parameter(t.name)+", "+(t.index==null?"Value(), {}":name(t.name,caseSet())+", [&](){ return "+expression(t.index,b)+"; }");emit.accept(names.get(t.name).name+" = fc."+(b.kind==INPUT?"read(":"readFile(")+literal(names.get(t.name).original)+", "+(b.kind==INPUT?literal(b.prompt==null?"":b.prompt)+", ":"")+tail+");");if(b.kind==INPUT)emit.accept("fc.step();");}
   else if(b.kind!=START&&b.kind!=PAUSE){if(b.kind==OPEN_FILE)emit.accept("fc.requireClosed("+o.fileReading+");");if(b.kind==WRITE_FILE)emit.accept("fc.requireWrite();");String e=expression(o.value,b);switch(b.kind){case OUTPUT:emit.accept("fc.emit("+e+", "+o.outputNewline+");");break;case CALL:emit.accept(e+";");break;case OPEN_FILE:emit.accept("fc.openFile("+o.fileReading+", "+e+");");break;case WRITE_FILE:emit.accept("fc.writeFile("+e+", "+o.fileNewline+");");break;case CLOSE_FILE:emit.accept("fc.closeFile("+o.fileReading+");");break;case TURTLE_FORWARD:case TURTLE_TURN:case TURTLE_HOME:case TURTLE_CLEAR:case TURTLE_PEN:emit.accept("fc.turtle("+b.kind+", "+e+", "+(b.kind==TURTLE_FORWARD?o.turtleDraw:o.turtleLeft)+");");break;default:throw new IllegalArgumentException("Blocco C++ non supportato.");}}
   emit.accept("return Value();");line("}",2,b);
  }
 }
}
